import{_ as e,c as i,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Finder 同步扩展","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/finder-sync.md","filePath":"zh-CN/guide/finder-sync.md","lastUpdated":1794112334000}'),o={name:"zh-CN/guide/finder-sync.md"};function l(n,a,d,s,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="finder-同步扩展" tabindex="-1">Finder 同步扩展 <a class="header-anchor" href="#finder-同步扩展" aria-label="Permalink to &quot;Finder 同步扩展&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Nicasa Finder 同步扩展会在 macOS 访达中添加一个工具栏按钮，让你无需打开 Nicasa 主应用就能快速处理图片文件。</p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h3><ul><li><strong>图片优化器</strong>：压缩并优化选中的图片</li><li><strong>AI 图像编辑器</strong>：用 AI 编辑选中的图片（修复、增强、填充等）</li><li><strong>通过 Finder 工具栏快速访问</strong></li><li><strong>支持同时选中多张图片</strong></li></ul><h2 id="安装与设置" tabindex="-1">安装与设置 <a class="header-anchor" href="#安装与设置" aria-label="Permalink to &quot;安装与设置&quot;">​</a></h2><h3 id="通过-nicasa-应用安装" tabindex="-1">通过 Nicasa 应用安装 <a class="header-anchor" href="#通过-nicasa-应用安装" aria-label="Permalink to &quot;通过 Nicasa 应用安装&quot;">​</a></h3><p>Finder 同步扩展随 Nicasa 主应用一起提供。安装应用后，启用该扩展：</p><ol><li>打开 <strong>系统设置</strong> &gt; <strong>扩展</strong> &gt; <strong>访达扩展</strong></li><li>打开 <strong>Nicasa Finder Sync</strong> 开关</li></ol><h3 id="工具栏按钮" tabindex="-1">工具栏按钮 <a class="header-anchor" href="#工具栏按钮" aria-label="Permalink to &quot;工具栏按钮&quot;">​</a></h3><p>启用后，Finder 工具栏中会出现一个 Nicasa 图标。</p><p>如果没有显示：</p><ol><li>在 Finder 工具栏上右键点击</li><li>选择 <strong>自定义工具栏…</strong></li><li>把 Nicasa 按钮拖到合适位置</li></ol><h2 id="使用-finder-工具栏按钮" tabindex="-1">使用 Finder 工具栏按钮 <a class="header-anchor" href="#使用-finder-工具栏按钮" aria-label="Permalink to &quot;使用 Finder 工具栏按钮&quot;">​</a></h2><h3 id="选择文件" tabindex="-1">选择文件 <a class="header-anchor" href="#选择文件" aria-label="Permalink to &quot;选择文件&quot;">​</a></h3><p>打开 Finder 并选中一张或多张图片。支持的格式：</p><ul><li><code>.jpg</code>、<code>.jpeg</code>、<code>.png</code>、<code>.gif</code>、<code>.bmp</code>、<code>.webp</code>、<code>.svg</code>、<code>.tiff</code>、<code>.ico</code></li></ul><h3 id="使用菜单" tabindex="-1">使用菜单 <a class="header-anchor" href="#使用菜单" aria-label="Permalink to &quot;使用菜单&quot;">​</a></h3><p>点击 Nicasa 工具栏按钮，然后选择：</p><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><strong>图片优化器</strong></td><td>压缩并优化选中的图片</td></tr><tr><td><strong>AI 图像编辑器</strong></td><td>在 Nicasa 的 AI 编辑器中打开选中的图片，进行修复、增强或图像填充</td></tr></tbody></table><blockquote><p>⚠️ <strong>注意</strong>：如果没有选中任何文件，按钮会发出提示音且不会执行操作。</p></blockquote><h3 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h3><ol><li>在 Finder 中选中图片</li><li>点击 Nicasa 工具栏按钮 → 选择所需操作</li><li>Nicasa 应用会自动打开并处理选中的图片</li></ol><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><ul><li>为获得最佳效果，请在你有访问权限的文件夹中选择图片</li><li>可以一次选中多个文件</li><li>如果某张图片无法打开，请确认它属于受支持的格式</li><li>该扩展与 macOS 沙盒机制良好配合——你只需在首次使用时授权访问</li></ul>',25)])])}const b=e(o,[["render",l]]);export{g as __pageData,b as default};
